/**
 * @module .claude/hooks/protect-files
 *
 * Claude Code `PreToolUse` hook for the Edit and Write tools. It stops Claude
 * from editing files that must never be changed by hand:
 *
 * - generated files (`*.generated.*`), which an import script rebuilds from
 *   source data, so hand edits would be overwritten and drift from the source;
 * - `.env` files, which hold local secrets (`.env.example` is allowed).
 *
 * Claude Code sends the tool call as JSON on stdin. Exiting with code 2 blocks
 * the edit and passes the stderr message back to Claude.
 */
import path from 'node:path';

/**
 * Reads all of stdin as a UTF-8 string.
 *
 * @returns The raw hook payload.
 */
async function readStdin() {
  const chunks = [];
  for await (const chunk of process.stdin) chunks.push(chunk);
  return Buffer.concat(chunks).toString('utf8');
}

let payload;
try {
  payload = JSON.parse(await readStdin());
} catch {
  process.exit(0); // Not a payload we understand: never block on our own bug.
}

const filePath = payload?.tool_input?.file_path;
if (typeof filePath !== 'string') process.exit(0);

const name = path.basename(filePath);

if (/\.generated\.[a-z0-9]+$/i.test(name)) {
  console.error(
    `${name} is generated by an import script. Change the script or its source data ` +
      'and re-run it instead of editing this file by hand.',
  );
  process.exit(2);
}

if (name === '.env' || (name.startsWith('.env.') && name !== '.env.example')) {
  console.error(
    `${name} holds local secrets and must not be edited by Claude. Update .env.example ` +
      'and ask the user to change their own .env.',
  );
  process.exit(2);
}

process.exit(0);
